import{_ as l,a0 as t,w as o,s as d,ao as r,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何对你的 Linux 系统进行压力测试 | LCTT x X-CMD","titleTemplate":false,"description":"如何对你的 Linux 系统进行压力测试 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何对你的 Linux 系统进行压力测试 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何对你的 Linux 系统进行压力测试 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200625 How to stress test your Linux system","title":"如何对你的 Linux 系统进行压力测试","tag":"202007","desc":""},"relativePath":"202007/20200625 How to stress test your Linux system.md","filePath":"[post].md"}'),c={name:"202007/20200625 How to stress test your Linux system.md"};function h(u,s,g,k,b,y){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何对你的-linux-系统进行压力测试" tabindex="-1">如何对你的 Linux 系统进行压力测试 <a class="header-anchor" href="#如何对你的-linux-系统进行压力测试" aria-label="Permalink to “如何对你的 Linux 系统进行压力测试”">​</a></h1><blockquote><p>如果你想了解 Linux 服务器在重压之下的运行情况，那么给 Linux 服务器施加压力是个不错的主意。在这篇文章中，我们将看一些工具，可以帮助你增加服务器压力并衡量结果。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/06/stress-test2_linux-penguin-stress-ball_hand-squeezing_by-digitalsoul-getty-images_1136841639-100850120-large.jpg" alt=""></p><p>为什么你会想给你的 Linux 系统施加压力呢？因为有时你可能想知道当一个系统由于大量运行的进程、繁重的网络流量、过多的内存使用等原因而承受很大的压力时，它的表现如何。这种压力测试可以帮助确保系统已经做好了 “上市” 的准备。</p><p>如果你需要预测应用程序可能需要多长时间才能做出反应，以及哪些（如果有的话）进程可能会在重负载下失败或运行缓慢，那么在前期进行压力测试是一个非常好的主意。</p><p>幸运的是，对于那些需要能够预测 Linux 系统在压力下的反应的人来说，你可以采用一些有用的技术和工具来使这个过程更容易。在这篇文章中，我们将研究其中的一些。</p><h3 id="自己动手做个循环" tabindex="-1">自己动手做个循环 <a class="header-anchor" href="#自己动手做个循环" aria-label="Permalink to “自己动手做个循环”">​</a></h3><p>第一种技术是在命令行上运行一些循环，观察它们对系统的影响。这种方式可以大大增加 CPU 的负荷。使用 <code>uptime</code> 或类似的命令可以很容易地看到结果。</p><p>在下面的命令中，我们启动了四个无尽循环。你可以通过添加数字或使用 bash 表达式，如 <code>{1...6}</code> 来代替 <code>1 2 3 4</code> 以增加循环次数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in 1 2 3 4; do while : ; do : ; done &amp; done</span></span></code></pre></div><p>在命令行上输入后，将在后台启动四个无尽循环：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in 1 2 3 4; do while : ; do : ; done &amp; done</span></span>
<span class="line"><span>[1] 205012</span></span>
<span class="line"><span>[2] 205013</span></span>
<span class="line"><span>[3] 205014</span></span>
<span class="line"><span>[4] 205015</span></span></code></pre></div><p>在这种情况下，发起了作业 1-4，作业号和进程号会相应显示出来。</p><p>要观察对平均负载的影响，请使用如下所示的命令。在本例中，<code>uptime</code> 命令每 30 秒运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ while true; do uptime; sleep 30; done</span></span></code></pre></div><p>如果你打算定期运行这样的测试，你可以将循环命令放入脚本 <code>watch-it</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  uptime</span></span>
<span class="line"><span>  sleep 30</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>在输出中，你可以看到平均负载是如何增加的，然后在循环结束后又开始下降。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 11:25:34 up 5 days, 17:27,  2 users,  load average: 0.15, 0.14, 0.08</span></span>
<span class="line"><span> 11:26:04 up 5 days, 17:27,  2 users,  load average: 0.09, 0.12, 0.08</span></span>
<span class="line"><span> 11:26:34 up 5 days, 17:28,  2 users,  load average: 1.42, 0.43, 0.18</span></span>
<span class="line"><span> 11:27:04 up 5 days, 17:28,  2 users,  load average: 2.50, 0.79, 0.31</span></span>
<span class="line"><span> 11:27:34 up 5 days, 17:29,  2 users,  load average: 3.09, 1.10, 0.43</span></span>
<span class="line"><span> 11:28:04 up 5 days, 17:29,  2 users,  load average: 3.45, 1.38, 0.54</span></span>
<span class="line"><span> 11:28:34 up 5 days, 17:30,  2 users,  load average: 3.67, 1.63, 0.66</span></span>
<span class="line"><span> 11:29:04 up 5 days, 17:30,  2 users,  load average: 3.80, 1.86, 0.76</span></span>
<span class="line"><span> 11:29:34 up 5 days, 17:31,  2 users,  load average: 3.88, 2.06, 0.87</span></span>
<span class="line"><span> 11:30:04 up 5 days, 17:31,  2 users,  load average: 3.93, 2.25, 0.97</span></span>
<span class="line"><span> 11:30:34 up 5 days, 17:32,  2 users,  load average: 3.64, 2.35, 1.04 &lt;== 循环停止</span></span>
<span class="line"><span> 11:31:04 up 5 days, 17:32,  2 users,  load average: 2.20, 2.13, 1.01      11:31:34 up 5 days, 17:33,  2 users,  load average: 1.40, 1.94, 0.98</span></span></code></pre></div><p>因为所显示的负载分别代表了 1、5 和 15 分钟的平均值，所以这些值需要一段时间才能恢复到系统接近正常的状态。</p><p>要停止循环，请发出像下面这样的 <code>kill</code> 命令 —— 假设作业号是 1-4，就像本篇文章前面显示的那样。如果你不确定，可以使用 <code>jobs</code> 命令来确认作业号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kill %1 %2 %3 %4</span></span></code></pre></div><h3 id="增加压力的专用工具" tabindex="-1">增加压力的专用工具 <a class="header-anchor" href="#增加压力的专用工具" aria-label="Permalink to “增加压力的专用工具”">​</a></h3><p>另一种方法是使用专门为你制造系统压力的工具。其中一种叫做 <code>stress</code>（压力），可以以多种方式对系统进行压力测试。<code>stress</code> 工具是一个工作负载生成器，提供 CPU、内存和磁盘 I/O 压力测试。</p><p>在使用 <code>--cpu</code> 选项时，<code>stress</code> 命令使用平方根函数强制 CPU 努力工作。指定的 CPU 数量越多，负载上升的速度就越快。</p><p>下面第二个脚本（<code>watch-it-2</code>）可以用来衡量对系统内存使用的影响。请注意，它使用 <code>free</code> 命令来查看加压的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat watch-it-2</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  free</span></span>
<span class="line"><span>  sleep 30</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>发起任务并观察压力：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --cpu 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./watch-it</span></span>
<span class="line"><span> 13:09:14 up 5 days, 19:10,  2 users,  load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span> 13:09:44 up 5 days, 19:11,  2 users,  load average: 0.68, 0.16, 0.05</span></span>
<span class="line"><span> 13:10:14 up 5 days, 19:11,  2 users,  load average: 1.20, 0.34, 0.12</span></span>
<span class="line"><span> 13:10:44 up 5 days, 19:12,  2 users,  load average: 1.52, 0.50, 0.18</span></span>
<span class="line"><span> 13:11:14 up 5 days, 19:12,  2 users,  load average: 1.71, 0.64, 0.24</span></span>
<span class="line"><span> 13:11:44 up 5 days, 19:13,  2 users,  load average: 1.83, 0.77, 0.30</span></span></code></pre></div><p>在命令行中指定的 CPU 越多，负载就增加的越快。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --cpu 4</span></span>
<span class="line"><span>$ ./watch-it</span></span>
<span class="line"><span> 13:47:49 up 5 days, 19:49,  2 users,  load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span> 13:48:19 up 5 days, 19:49,  2 users,  load average: 1.58, 0.38, 0.13</span></span>
<span class="line"><span> 13:48:49 up 5 days, 19:50,  2 users,  load average: 2.61, 0.75, 0.26</span></span>
<span class="line"><span> 13:49:19 up 5 days, 19:50,  2 users,  load average: 3.16, 1.06, 0.38</span></span>
<span class="line"><span> 13:49:49 up 5 days, 19:51,  2 users,  load average: 3.49, 1.34, 0.50</span></span>
<span class="line"><span> 13:50:19 up 5 days, 19:51,  2 users,  load average: 3.69, 1.60, 0.61</span></span></code></pre></div><p><code>stress</code> 命令也可以通过 <code>--io</code>（输入/输出）和 <code>--vm</code>（内存）选项增加 I/O 和内存的负载来给系统施加压力。</p><p>在接下来的这个例子中，运行这个增加内存压力的命令，然后启动 <code>watch-it-2</code> 脚本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --vm 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ watch-it-2</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      662160     2519164        8868     2905740     5117548</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      803464     2377832        8864     2905768     4976248</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      968512     2212772        8864     2905780     4811200</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p><code>stress</code> 的另一个选项是使用 <code>--io</code> 选项为系统添加输入/输出活动。在这种情况下，你可以使用这样的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --io 4</span></span></code></pre></div><p>然后你可以使用 <code>iotop</code> 观察受压的 I/O。注意，运行 <code>iotop</code> 需要 root 权限。</p><p>之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iotop -o</span></span>
<span class="line"><span>Total DISK READ:         0.00 B/s | Total DISK WRITE:        19.36 K/s</span></span>
<span class="line"><span>Current DISK READ:       0.00 B/s | Current DISK WRITE:      27.10 K/s</span></span>
<span class="line"><span>    TID  PRIO  USER     DISK READ  DISK WRITE  SWAPIN     IO&gt;    COMMAND</span></span>
<span class="line"><span> 269308 be/4 root        0.00 B/s    0.00 B/s  0.00 %  1.24 % [kworker~fficient]</span></span>
<span class="line"><span>    283 be/3 root        0.00 B/s   19.36 K/s  0.00 %  0.26 % [jbd2/sda1-8]</span></span></code></pre></div><p>之后：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Total DISK READ:         0.00 B/s | Total DISK WRITE:         0.00 B/s</span></span>
<span class="line"><span>Current DISK READ:       0.00 B/s | Current DISK WRITE:       0.00 B/s</span></span>
<span class="line"><span>    TID  PRIO  USER     DISK READ  DISK WRITE  SWAPIN     IO&gt;    COMMAND</span></span>
<span class="line"><span> 270983 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 51.45 % stress --io 4</span></span>
<span class="line"><span> 270984 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 51.36 % stress --io 4</span></span>
<span class="line"><span> 270985 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 50.95 % stress --io 4</span></span>
<span class="line"><span> 270982 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 50.80 % stress --io 4</span></span>
<span class="line"><span> 269308 be/4 root        0.00 B/s    0.00 B/s  0.00 %  0.09 % [kworker~fficient]</span></span></code></pre></div><p><code>stress</code> 只是给系统增加压力的若干工具之一。另一个较新的工具，<code>stress-ng</code>，将在以后的文章中介绍。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>用于系统压力测试的各种工具可以帮助你预测系统在真实世界的情况下如何响应，在这些情况下，它们受到增加的流量和计算需求。</p><p>虽然我们在文章中展示的是创建和测量各种类型的压力的方法，但最终的好处是压力如何帮助确定你的系统或应用程序对它的反应。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3563334/how-to-stress-test-your-linux-system.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3563334/how-to-stress-test-your-linux-system.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(c,[["render",h]]);export{v as __pageData,C as default};
